#include <bits/stdc++.h>
using namespace std;

using vec = vector;
#define pb push_back
#define FOR(i, a, b) for(int i = (a); i < (b); i++)
#define FORE(i, a, b) for(int i = (a); i <= (b); i++)
#define FORD(i, a, b) for(int i = (a); i >= (b); i--)
const long long INF64 = 1e18;
typedef long long ll;

struct Edge {
  int from;
  int to;
  int f;
  int cost;

  Edge() {};

  Edge(int _from, int _to, int _f, int _cost) 
    : from(_from), to(_to), f(_f), cost(_cost) {};
};

vec<Edge> e;

const int N = 1e6 + 7;
vec<int> g[N];

ll totalCost = 0;
ll dist[N];
int pred[N];
int pe[N];
int inq[N];

int source = N - 2;
int target = N - 1;

int residualCapacity(int x) {
  return e[x].to - e[x].f;
}

void runDijkstra() {
  FOR(i, 0, N) {
    dist[i] = INF64;
    pred[i] = -1;
    pe[i] = -1;
    inq[i] = 0;
  }
  dist[source] = 0;
  queue<int> q;
  q.push(source);
  inq[source] = 1;
  while (!q.empty()) {
    int k = q.front(); q.pop();
    inq[k] = 0;
    for (auto edgeIdx : g[k]) {
      if (!residualCapacity(edgeIdx)) continue;
      int cst = e[edgeIdx].cost;
      int y = e[edgeIdx].from;
      if (dist[y] > dist[k] + cst) {
        dist[y] = dist[k] + cst;
        pred[y] = k;
        pe[y] = edgeIdx;
        if (inq[y] == 0) {
          inq[y] = 1;
          q.push(y);
        }
      }
    }
  }
}

void augmentFlow() {
  runDijkstra();
  int current = target;
  while (current != source) {
    e[pe[current]].f++;
    e[pe[current] ^ 1].f--;
    current = pred[current];
  }
  totalCost += dist[target];
}

void addEdge(int x, int y, int capacity, int cost) {
  g[x].push_back(e.size());
  e.emplace_back(x, y, 0, cost);
  g[y].push_back(e.size());
  e.emplace_back(y, x, capacity, -cost);
}

int n, m, k, c, d;
const int timeLayers = 101;

void buildGraph() {
  scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);
  for (int i = 0; i < k; i++) {
    int x; scanf("%d", &x);
    --x;
    addEdge(source, x, 1, 0);
  }
  for (int i = 0; i < timeLayers; i++) {
    addEdge(i * n, target, k, i * c);
  }
  for (int i = 0; i < m; i++) {
    int x, y; scanf("%d %d", &x, &y);
    --x; --y;
    for (int t = 0; t < timeLayers - 1; t++) {
      for (int j = 0; j < k; j++) {
        addEdge(x + t * n, y + t * n + n, 1, d * (j * 2 + 1));
      }
    }
    for (int t = 0; t < timeLayers - 1; t++) {
      for (int j = 0; j < k; j++) {
        addEdge(y + t * n, x + t * n + n, 1, d * (j * 2 + 1));
      }
    }
  }
}

void solve() {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < timeLayers - 1; j++) {
      addEdge(i + j * n, i + j * n + n, k, 0);
    }
  }
  for (int i = 0; i < k; i++) {
    augmentFlow();
  }
  printf("%lld\n", totalCost);
}

int main() {
  buildGraph();
  solve();
  return 0;
}
